using System;using System.IO;using System.Reflection;using System.Text;using System.Windows.Forms;
class HeadlessUiChecks {static BindingFlags f=BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic,i=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static int checks;static void Check(bool ok,string label){if(!ok)throw new Exception(label);++checks;Console.WriteLine("PASS "+label);}static object Field(object o,string name){return o.GetType().GetField(name,i).GetValue(o);}static object Call(object o,string name,params object[] a){try{return o.GetType().GetMethod(name,i).Invoke(o,a);}catch(TargetInvocationException e){throw e.InnerException;}}
[STAThread]static int Main(string[]a){Console.OutputEncoding=new UTF8Encoding(false);try{Application.EnableVisualStyles();var asm=Assembly.LoadFrom(a[0]);var l=asm.GetType("L");l.GetMethod("Initialize",f).Invoke(null,new object[]{"zh-CN"});using(var form=(Form)Activator.CreateInstance(asm.GetType("InstallerForm"),true)){form.GetType().GetProperty("PreviewOnly",i).SetValue(form,true,null);var scale=(NumericUpDown)Field(form,"subtitleScaleBox");scale.Value=1.4m;var chinese=Field(form,"chineseBox");chinese.GetType().GetProperty("Checked").SetValue(chinese,false,null);((CheckBox)Field(form,"nodeFixBox")).Checked=false;
foreach(string language in new[]{"zh-CN","en"}){l.GetMethod("SetLanguage",f).Invoke(null,new object[]{language});Call(form,"ApplyLanguage");form.PerformLayout();Check(!form.Visible,"headless form remains hidden "+language);var o=Call(form,"ReadOptions");Check(!(bool)o.GetType().GetField("Chinese").GetValue(o)&&!(bool)o.GetType().GetField("NodeFix").GetValue(o),"language switch preserves component preferences "+language);Check((decimal)o.GetType().GetField("SubtitleScale").GetValue(o)==1.4m,"language switch preserves numeric setting "+language);var install=(Control)Field(form,"installButton");var settings=(Control)Field(form,"markerSettingsButton");Check(install.Bottom<=form.ClientSize.Height&&install.Right<=form.ClientSize.Width,"installation button fits main form "+language);Check(settings.Text==(language=="en"?"More features from MarkerPatch":"其他由 MarkerPatch 提供的功能改善"),"manual settings entry translated "+language);}
}Console.WriteLine("HEADLESS UI CHECKS PASSED "+checks);return 0;}catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}}
